"use strict";
const test=require("node:test");const assert=require("node:assert/strict");const {buildAnchor,validateAnchor,selectNextTask,appendHistoryEntry}=require("../bootstrap-context");const {selectActiveProjectAndPlan}=require("../active-plan");
test("builds five sourced blocks",()=>{const a=validateAnchor(buildAnchor());assert.deepEqual(a.blocks.map(x=>x.id),["architecture","roadmap","flow","rules","nextStep"]);for(const b of a.blocks)assert.ok(b.sources.length);});
test("uses active CMS plan in planning blocks",()=>{const a=buildAnchor();for(const id of ["roadmap","flow","nextStep"]){const b=a.blocks.find(x=>x.id===id);assert.ok(b.sources.includes("site-context/registry/plans/PLAN-EDITORIAL-CMS-MVP.json"));assert.ok(!b.sources.some(x=>x.includes("PLAN-ANCHOR-MVP")));}});
test("recovers governance task and command",()=>{const selected=selectActiveProjectAndPlan();assert.ok(selected&&typeof selected==="object");assert.ok(selected.projects&&typeof selected.projects==="object"&&!Array.isArray(selected.projects));assert.ok(Array.isArray(selected.projects.projects));const activeProjects=selected.projects.projects.filter(x=>x.status==="in_progress");assert.equal(activeProjects.length,1);const activeProject=activeProjects[0];assert.equal(activeProject.id,"EPIC-004");assert.ok(selected.activeProject);assert.equal(selected.activeProject.id,activeProject.id);assert.equal(selected.activeProject.status,"in_progress");assert.ok(selected.plan);assert.equal(selected.plan.id,"PLAN-EDITORIAL-CMS-MVP");assert.equal(selected.plan.projectId,selected.activeProject.id);assert.match(selected.planPath,/PLAN-EDITORIAL-CMS-MVP\.json$/);const currentPhase=selected.plan.phases.find(x=>x.id===selected.plan.currentPhase);assert.ok(currentPhase);assert.equal(currentPhase.status,"in_progress");const activeTasks=(currentPhase.tasks||[]).filter(x=>x.status==="in_progress");assert.equal(activeTasks.length,1);const activeTask=activeTasks[0];assert.notEqual(activeTask.status,"completed");const a=buildAnchor();const n=a.blocks.find(x=>x.id==="nextStep").content;assert.equal(n.task,activeTask.id);if(typeof activeTask.nextCommand==="string"&&activeTask.nextCommand.trim())assert.equal(n.command,activeTask.nextCommand);else assert.equal(n.command,null);});
test("selects in_progress before planned and returns null command when absent",()=>{const p={currentPhase:"P",phases:[{id:"P",tasks:[{id:"A",status:"planned"},{id:"B",status:"in_progress"}]}]};assert.equal(selectNextTask(p).id,"B");assert.equal(selectNextTask({currentPhase:"P",phases:[{id:"P",tasks:[]}]}),null);});
test("preserves previousHash chain",()=>{const h={entries:[{hash:"prior"}]};const a={generatedAt:"now",blocks:[{content:{currentProject:{id:"EPIC"},currentPhase:{id:"PHASE"}}}]};appendHistoryEntry(h,a,"current");assert.equal(h.entries[1].previousHash,"prior");});